describe('Notification Message Rendered Tests', () => {
  it('should display the notification with a success message', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('a[href="#/notification_message_rendered"]').click();
    cy.get('#flash').should('be.visible');
    cy.get('#flash').contains('Action successful').should('be.visible');
    cy.get('#flash .close').click();
    cy.url().should('include', '/notification_message_rendered');
  });

  it('should not change the URL when clicking the link without triggering an action', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('a[href="#/notification_message_rendered"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/notification_message_rendered');
  });
});
